const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let S=null,tab='cards',master='players',busy=false,resultsQuery='',playersQuery='',cardsQuery='',rosterQuery='';
const categories=['1ra','2daA','2daB','3ra'];
const eye='<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>';
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),5000);}

const me=()=>S.players.find(p=>p.id===S.me), player=id=>S.players.find(p=>p.id===id), name=id=>{const p=player(id);return p?`${p.name} ${p.surname}`: 'Sin asignar';},start=g=>S.members.find(m=>m.groupId===g)?.start,order=h=>Array.from({length:18},(_,i)=>(h-1+i)%18);
const relative=n=>n===0?'E':n>0?'+'+n:String(n);
function stats(c){c=confirmedCard(c);let strokes=0,par=0,played=0;c.scores.forEach((v,i)=>{if(v!==null){strokes+=v;par+=S.course.pars[i];played++;}});return {strokes,played,relative:strokes-par};}
const result=(v,p)=>MacarenaScoring.result(v,p);
function draftKey(g,h){return `macarena-input:${S.me}:${g}:${h}${S.tournamentGeneration?':'+S.tournamentGeneration:''}`;}
function draftValue(g,h,value){if(!S.permissions[g])return value??'';const key=draftKey(g,h),draft=localStorage.getItem(key);if(draft!==null){try{if(!validHoleText(draft))throw Error('Borrador inválido');MacarenaScoring.validateSequence(S.cards[g].scores,start(g),h,MacarenaScoring.parse(draft));}catch{localStorage.removeItem(key);localStorage.removeItem(key+':base');return value??'';}}return draft??value??'';}
function draftErrors(g){return Array.from({length:18},(_,h)=>{try{MacarenaScoring.parse(draftValue(g,h,S.cards[g].scores[h]));return '';}catch{return 'Hoyo '+(h+1)+': registre un número entero entre 1 y 19';}}).filter(Boolean).join('. ');}
function hasDraft(g){return Array.from({length:18},(_,h)=>{const value=localStorage.getItem(draftKey(g,h));return value!==null&&value!==String(S.cards[g].scores[h]??'');}).some(Boolean);}
function cardSummary(c){const v=stats(c),par=v.relative>0?'+ '+v.relative:v.relative<0?'- '+Math.abs(v.relative):'E';return `<strong class="completed-total">Total: ${v.played===18?v.strokes:'—'} / ${v.played?par:'—'}</strong><span>${v.played}/18 hoyos</span>`;}
function halfSummary(c,offset){c=confirmedCard(c);const v=MacarenaScoring.subtotal(c.scores,offset);return `<span>Subtotal ${offset+1}–${offset+9}</span><strong>${v.played?v.strokes:'—'}</strong><small>${v.played}/9 hoyos</small>`;}

const button=(text,attrs='',cls='')=>`<button class="${cls}" ${attrs}>${text}</button>`;
function login(){return `<main class="login"><div class="login-brand"><img src="${esc('/tournament-logo.jpg?v='+(S?.tournament?.logoVersion||'default'))}" alt="Club Amigos del Golf · Una familia"></div><form id="login"><h1>Bienvenido a tu torneo</h1><label>Cédula<input name="id" inputmode="numeric" pattern="[0-9]{1,15}" maxlength="15" autocomplete="username" required></label><label>Clave<input name="password" type="password" maxlength="64" autocomplete="current-password" required></label><button class="primary">Ingresar</button><p class="form-error" id="loginError" role="alert"></p></form><footer>Patrocinado por Tigers Ryder</footer></main>`;}
function baseRender(){if(!S){$('#app').innerHTML=login();$('#login').onsubmit=async e=>{e.preventDefault();try{await api('login',Object.fromEntries(new FormData(e.target)));S=await api('state');render();}catch(e){$('#loginError').textContent=e.message;}};return;}
 const active=S.groups.filter(g=>g.active),inField=active.filter(g=>stats(S.cards[g.id]).played&&(!S.cards[g.id].finalized||S.cards[g.id].finalized.pending)).length,finished=active.filter(g=>S.cards[g.id].finalized&&!S.cards[g.id].finalized.pending).length;
 $('#app').innerHTML=`<header><div class="brand"><img src="${esc('/tournament-logo.jpg?v='+(S?.tournament?.logoVersion||'default'))}" alt="Club Amigos del Golf · Una familia"></div><div class="account"><span class="account-identity"><small class="account-version">Versión 3.0. qa by Julián Ocampo</small><small class="account-welcome">Bienvenido</small><span class="account-name">${esc(name(S.me))}</span>${me().admin?'<small>Administrador</small>':''}</span>${button('Salir','data-action="logout"','ghost')}</div></header><main><section class="overview overview-compact"><div class="counters"><div><strong>${inField}</strong><span>Partidos en campo</span></div><div><strong>${finished}</strong><span>Finalizados</span></div></div></section><div class="toolbar"><nav>${[['cards','Tarjetas'],['results','Resultados'],...(me().admin?[['masters','Maestros'],['settings','Configuración']]:[])].map(([k,v])=>button(k==='settings'?'<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 3 .5-1h5l.5 3 2 1 2.7-1 2 3.5-2.2 2v3l2.2 2-2 3.5-2.7-1-2 1-.5 3h-5l-.5-3-2-1-2.7 1-2-3.5 2.2-2v-3l-2.2-2 2-3.5L7 6l2-1Z"/><circle cx="12" cy="12" r="3"/></svg>':v,`data-tab="${k}" ${k==='settings'?'aria-label="Configuración" title="Configuración"':''} aria-current="${tab===k?'page':'false'}"`,tab===k?'selected':'')).join('')}</nav></div><section id="content">${tab==='cards'?cards():tab==='results'?leaderboard():tab==='settings'?settings():masters()}</section><footer>Patrocinado por Tigers Ryder <span>Actualización automática</span></footer></main>`;
 $('#rain-finalization')?.addEventListener('change',async e=>{const control=e.target;control.disabled=true;try{S=await api('rain-finalization',{enabled:control.checked});render();}catch(e){control.checked=!!S.rainFinalization;toast(e.message);}finally{control.disabled=false;}});
 $('#editing')?.addEventListener('change',async e=>{const control=e.target;control.disabled=true;try{S=await api('editing',{enabled:control.checked});render();}catch(e){control.checked=S.editing;toast(e.message);}finally{control.disabled=false;}});
}
function hasPending(id){return !!engine.record?.pending.some(o=>o.groupId===id);}
function sequenceNote(id){if(hasPending(id))return 'Esperando confirmación del guardado';const next=MacarenaScoring.nextHole(S.cards[id].scores,start(id));return next<0?'18 hoyos completos':'Siguiente: hoyo '+(next+1);}
function orderedCardGroups(){
 const own=S.members.find(m=>m.playerId===S.me),assigned=new Set(S.assignments.filter(a=>a.playerId===S.me).map(a=>a.groupId)),hole=own?.start;
 const priority=g=>assigned.has(g.id)?0:g.id===own?.groupId?1:hole&&start(g.id)===hole?2:3;
 return S.groups.filter(g=>g.active).sort((a,b)=>priority(a)-priority(b)||(start(a.id)||19)-(start(b.id)||19)||a.name.localeCompare(b.name,'es',{numeric:true,sensitivity:'base'})||a.id.localeCompare(b.id,'es',{numeric:true}));
}
function cards(){return `<div class="board-search"><input id="cards-search" type="search" value="${esc(cardsQuery)}" placeholder="Buscar grupo, integrante o capitán" aria-label="Buscar tarjetas"><div id="cards-filter-status" class="cards-filter-status" hidden><span id="cards-filter-count" role="status" aria-live="polite"></span>${button('Ver todas','data-action="clear-cards-search"','ghost')}</div></div><p id="cards-empty" class="muted" hidden>No hay tarjetas que coincidan.</p><div class="legend">${MacarenaScoring.palette.map(([c,t])=>`<span><i class="${c}"></i>${t}</span>`).join('')}</div><div class="cards">${orderedCardGroups().map(g=>{const c=S.cards[g.id],v=stats(c),h=start(g.id),writer=S.assignments.find(a=>a.groupId===g.id),allowed=S.permissions[g.id];return `<article class="card ${c.finalized&&!c.finalized.pending?'card-finalized':''}" data-card="${g.id}" data-card-search="${esc(normalizeSearch([g.name,...S.members.filter(m=>m.groupId===g.id).map(m=>name(m.playerId))].join(' ')))}">${c.finalized&&!c.finalized.pending?'<div class="finalized-banner"><span class="finalized-stamp" role="status">✓ FINALIZADA</span></div>':''}<div class="card-top"><div><p class="eyebrow">SALIDA ${h?'HOYO '+h:'SIN CONFIGURAR'}</p><h2>${esc(g.name)} ${button(eye,`data-action="members" data-id="${g.id}" aria-label="Ver integrantes de ${esc(g.name)}"`,'eye')}</h2><p class="muted">Capitán: ${groupCaptain(g.id)?esc(name(groupCaptain(g.id).id)):'Sin asignar'}</p></div><div class="card-score">${cardSummary(c)}</div></div><div class="card-meta"><span>Anota: <b>${esc(name(writer?.playerId))}</b></span><span class="status">${c.finalized?(c.finalized.pending?'Firmada · Pendiente de enviar':c.finalized.rain?'Finalizada por lluvia':c.finalized.administrative?'Cierre administrativo':'Finalizada'):allowed?'Puede editar':'Solo lectura'}</span></div>${[0,9].map(offset=>`<div class="score-row"><div class="holes">${Array.from({length:9},(_,j)=>offset+j).map(i=>{const [color,label]=result(c.scores[i],S.course.pars[i]);return `<label class="hole ${color} ${i===h-1?'starting-hole':''}" title="${label}${i===h-1?' · Hoyo de salida':''}"><span>H${i+1}</span><small>PAR ${S.course.pars[i]}</small><input type="text" inputmode="numeric" pattern="([1-9]|1[0-9])" maxlength="2" enterkeyhint="next" autocomplete="off" value="${esc(draftValue(g.id,i,c.scores[i]))}" placeholder="—" data-group="${g.id}" data-hole="${i}" aria-label="${esc(g.name)} hoyo ${i+1}, par ${S.course.pars[i]}, ${label}" ${!allowed||hasPending(g.id)||!MacarenaScoring.canRecord(c.scores,h,i)?'disabled':''}></label>`;}).join('')}</div><div class="half-total" data-offset="${offset}">${halfSummary(c,offset)}</div></div>`).join('')}<p class="sequence-note">${!c.finalized&&allowed?sequenceNote(g.id):''}</p><p class="score-error" role="alert">${esc(draftErrors(g.id))}</p><p class="card-save-state" role="status" aria-live="polite"></p><div class="card-bottom"><div>${button('Descargar tarjeta',`data-action="download" data-id="${g.id}" ${!c.finalized||c.finalized.pending?'disabled title="Disponible al finalizar la tarjeta"':''}`)}${me().admin?button('Reiniciar tarjeta',`data-action="reset-card" data-id="${g.id}"`,'danger'):''}${c.finalized?(me().admin&&!c.finalized.pending?button('Reabrir',`data-action="reopen" data-id="${g.id}"`):''):button(me().admin&&v.played!==18?'Finalizar como admin':'Finalizar y firmar',`data-action="finalize" data-id="${g.id}" ${!allowed||hasPending(g.id)||v.played!==18&&!me().admin&&!S.rainFinalization?'disabled':''}`,'primary')}</div></div></article>`;}).join('')}</div>`;}

function normalizeSearch(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').trim();}
function groupCaptain(id){return S.members.filter(m=>m.groupId===id&&m.captain).map(m=>S.players.find(p=>p.id===m.playerId)).find(p=>p?.active);}
function filterResults(){const query=normalizeSearch(resultsQuery),rows=document.querySelectorAll('[data-result-search]');let visible=0;rows.forEach(row=>{row.hidden=!row.dataset.resultSearch.includes(query);if(!row.hidden)visible++;});const empty=$('#results-empty');if(empty)empty.hidden=visible!==0;}
document.addEventListener('input',e=>{if(e.target.id==='results-search'){resultsQuery=e.target.value;filterResults();}});
const cardLinkIcon='<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M8 9v11M13 13h4M13 16h4"/></svg>';
function openGroupCard(id){cardsQuery='';tab='cards';render();const target=[...document.querySelectorAll('[data-card]')].find(card=>card.dataset.card===id);if(!target)return;target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});target.classList.add('card-navigation-highlight');setTimeout(()=>target.classList.remove('card-navigation-highlight'),2500);}
function leaderboard(){const rows=S.groups.filter(g=>g.active).map(g=>({g,c:S.cards[g.id],v:stats(S.cards[g.id])})).sort((a,b)=>(!a.v.played)-(!b.v.played)||a.v.relative-b.v.relative);const ownId=S.members.find(m=>m.playerId===S.me)?.groupId,own=rows.find(r=>r.g.id===ownId),ownRank=own?.v.played?rows.findIndex(r=>r.v.played&&r.v.relative===own.v.relative)+1:null,ownTied=own?.v.played&&rows.filter(r=>r.v.played&&r.v.relative===own.v.relative).length>1,ownPar=own?.v.played?(own.v.relative>0?'+ '+own.v.relative:own.v.relative<0?'- '+Math.abs(own.v.relative):'E'):'—';return `<div class="leaderboard"><div class="board-heading"><p class="eyebrow">Amigos del Golf - Scramble</p><div class="board-title-row"><h2>Tabla de posiciones</h2>${own?`<p class="board-own-position">Eres ${esc(own.g.name)} y Tú Posición es ${ownRank?ownRank:'—'} / <span class="board-own-score-label">Score <span class="board-own-score">${ownPar}</span></span></p>`:''}</div></div><div class="board-search"><input id="results-search" type="search" value="${esc(resultsQuery)}" placeholder="Buscar grupo o capitán" aria-label="Buscar grupo o capitán" autocomplete="off"></div><div class="table-scroll"><table><thead><tr><th>Pos</th><th>Grupo</th><th>Par</th><th>Jugados</th><th>Hoyo<br>Salida</th><th>Golpes<br>Totales</th></tr></thead><tbody>${rows.map(({g,c,v})=>{const rank=rows.findIndex(r=>r.v.played&&r.v.relative===v.relative)+1,tied=rows.filter(r=>r.v.played&&r.v.relative===v.relative).length>1,finished=!!c.finalized&&!c.finalized.pending,captain=groupCaptain(g.id);return `<tr class="${g.id===ownId?'board-own-row':''}" data-result-group="${g.id}" data-result-search="${esc(normalizeSearch([g.id,g.name,captain?.name,captain?.surname].join(' ')))}"><td>${v.played?rank:'—'}</td><td><span class="board-group">${esc(g.name)} ${button(eye,`data-action="members" data-id="${g.id}" aria-label="Ver integrantes de ${esc(g.name)}"`,'eye')}${button(cardLinkIcon,`data-action="open-card" data-id="${g.id}" aria-label="Ir a tarjeta de ${esc(g.name)}" title="Ir a tarjeta"`,'eye card-link')}</span><small class="board-captain">${captain?esc(captain.name+' '+captain.surname):'Sin capitán asignado'}</small></td><td class="board-par ${v.relative<0?'under':''}">${v.played?relative(v.relative):'—'}</td><td>${v.played===0?'Sin Comenzar':finished&&v.played===18?'F':v.played}${finished&&v.played<18?`<small class="awaiting-signature">${c.finalized.rain?'Finalizada por lluvia':'Cierre administrativo'}</small>`:!finished&&v.played===18?'<small class="awaiting-signature">Sin finalizar</small>':''}</td><td>${start(g.id)||'—'}</td><td>${finished?v.strokes:'—'}</td></tr>`;}).join('')}</tbody></table></div><p id="results-empty" class="board-note" hidden>No hay grupos que coincidan con la búsqueda.</p><p class="board-note">F: tarjeta firmada y finalizada con 18 hoyos. Los golpes totales aparecen al confirmar el cierre.</p></div>`;}

let historyFilter='';
function filterHistory(){let visible=0;document.querySelectorAll('[data-history-operation]').forEach(row=>{row.hidden=!!historyFilter&&row.dataset.historyOperation!==historyFilter;if(!row.hidden)visible++;});const empty=$('#history-empty');if(empty)empty.hidden=visible>0;}
document.addEventListener('change',e=>{if(e.target.id==='history-filter'){historyFilter=e.target.value;historyPage=1;loadHistory();}});
document.addEventListener('click',e=>{if(!e.target.closest('[data-clear-history]')||!me()?.admin)return;modal(`<h2>¿Borrar todo el historial?</h2><p>Se eliminarán todos los registros del historial, incluidos los que no aparecen con el filtro actual. Las tarjetas y los maestros se conservarán.</p><div class="form-actions">${button('Cancelar','data-action="close"')}${button('Sí, borrar historial','id="confirmClearHistory"','danger')}</div>`);$('#confirmClearHistory').onclick=async e=>{e.target.disabled=true;try{S=await api('clear-history',{confirm:true});historyRows=[];$('#modal').close();render();await loadHistory();toast('Historial borrado');}catch(err){toast(err.message);e.target.disabled=false;}};});
let historyRows=[],historyOwner=null,historyGeneration=null,historyRequest=0,historyPage=1,historyTotal=0,historyPages=1,historyFrom='',historyTo='',historyConsulted='';
function historyTable(){if(historyOwner!==S.me||historyGeneration!==(S.tournamentGeneration||0)){historyRows=[];historyOwner=S.me;historyGeneration=S.tournamentGeneration||0;historyPage=1;historyTotal=0;historyPages=1;historyConsulted='';}return `<div class="history-controls"><label>Funcionalidad<select id="history-filter">${[['','Todas'],...[...new Set(['Tarjeta Digitar Hoyo','Tarjeta Editar Hoyo','Tarjeta Finalizar','Tarjeta Reiniciar Tarjeta','Tarjeta Descargar','Tarjeta Reabrir','Maestros Jugadores','Maestros Grupos','Maestros Grupo Jugador','Maestro Asignación Tarjetas','Configuración Torneo','Configuración Cancha','Configuración Reiniciar Tarjetas','Configuración Historial Reiniciar Historial','Configuración Reiniciar Torneo','Configuración Habilitar Edición','Configuración Finalizado por lluvia',...historyRows.map(a=>a.functionality).filter(Boolean)])].map(v=>[v,v])].map(([v,t])=>`<option value="${esc(v)}" ${historyFilter===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Desde<input id="history-from" type="date" value="${esc(historyFrom)}"></label><label>Hasta<input id="history-to" type="date" value="${esc(historyTo)}"></label>${button('Consultar','data-history-query')}${button('Borrar historial','data-clear-history','danger')}</div><p class="muted">${historyConsulted?'Consultado: '+esc(historyConsulted):'Abre Historial para consultar.'}</p><div class="history-pages">${button('Anterior',`data-history-page="${historyPage-1}" ${historyPage<=1?'disabled':''}`)}<span>Página ${historyPage} de ${historyPages} · ${historyTotal} registros</span>${button('Siguiente',`data-history-page="${historyPage+1}" ${historyPage>=historyPages?'disabled':''}`)}</div><div class="table-scroll"><table class="history-table"><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Descripción</th><th>Funcionalidad</th></tr></thead><tbody>${historyRows.map(a=>`<tr data-history-operation="${esc(a.functionality||'No registrado')}">${[new Date(a.at).toLocaleString('es-CO'),name(a.user),a.area||a.action,a.description||'Registro anterior sin descripción detallada.',a.functionality||'No registrado'].map(value=>`<td>${esc(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p id="history-empty" class="muted" hidden>No hay registros para este filtro.</p>`;}
function settings(){if(!me().admin)return '';return `<div class="master-panel settings-panel"><h2>Configuración</h2><section class="settings-section"><label class="editing-switch"><span>Habilitar edición de tarjetas</span><input id="editing" type="checkbox" role="switch" ${S.editing?'checked':''}><span class="editing-state" aria-hidden="true"></span></label></section><section class="settings-section"><label class="editing-switch"><span>Habilitar Finalizado por lluvia</span><input id="rain-finalization" type="checkbox" role="switch" ${S.rainFinalization?'checked':''}><span class="editing-state" aria-hidden="true"></span></label></section><section class="settings-section"><div class="section-heading"><h3>Torneo</h3>${button('Configurar torneo','data-config="tournament"','primary')}</div><div class="table-scroll"><table><thead><tr><th>Título</th><th>Descripción</th><th>Fecha</th></tr></thead><tbody><tr><td>${esc(S.tournament?.title)}</td><td>${esc(S.tournament?.subtitle)}</td><td>${esc(S.tournament?.date||'Por definir')}</td></tr></tbody></table></div></section><section class="settings-section"><div class="section-heading"><h3>Cancha</h3>${button('Configurar cancha','data-config="course"','primary')}</div><h3>${esc(S.course.name)} · Par ${S.course.pars.reduce((a,b)=>a+b,0)}</h3><div class="course-grid">${S.course.pars.map((p,i)=>`<div><span>Hoyo ${i+1}</span><strong>${p}</strong><small>PAR</small></div>`).join('')}</div></section><section class="settings-section"><h3>Reiniciar todas las tarjetas</h3><p>Elimina los golpes, las firmas y el estado de finalización de todas las tarjetas. Conserva jugadores, grupos, cancha y asignaciones.</p>${button('Reiniciar todas las tarjetas','data-action="reset-cards"','danger')}</section><section class="settings-section"><h3>Reiniciar Torneo</h3><p>Borra el torneo y su configuración para empezar desde cero. Conserva los jugadores administradores, sus claves y el último logo cargado.</p>${button('Reiniciar Torneo','data-action="reset-tournament"','danger')}</section><details class="settings-section" id="settings-history"><summary>Historial</summary><div id="history-content">${historyTable()}</div></details></div>`;}
function resetCard(id){if(!me().admin)return;const group=S.groups.find(g=>g.id===id),revision=S.cards[id].revision;modal(`<h2>¿Reiniciar ${esc(group.name)}?</h2><p>Se eliminarán los golpes, las firmas y el cierre de esta tarjeta. Las demás tarjetas no cambiarán. Esta acción no se puede deshacer desde la aplicación.</p><div class="form-actions">${button('Cancelar','data-action="close"')}${button('Sí, reiniciar tarjeta','id="confirmResetCard"','danger')}</div>`);$('#confirmResetCard').onclick=async e=>{e.target.disabled=true;try{S=await api('reset-card',{groupId:id,revision,confirm:true});$('#modal').close();render();toast('La tarjeta de '+group.name+' quedó sin jugar');}catch(err){toast(err.message);e.target.disabled=false;}};}
function resetCards(){if(!me().admin)return;const revisions=Object.fromEntries(Object.entries(S.cards).map(([id,c])=>[id,c.revision]));modal(`<h2>¿Reiniciar todas las tarjetas?</h2><p>Se eliminarán todos los golpes, firmas y cierres. Las tarjetas quedarán sin jugar. Esta acción no se puede deshacer desde la aplicación.</p><div class="form-actions">${button('Cancelar','data-action="close"')}${button('Sí, reiniciar todas','id="confirmReset"','danger')}</div>`);$('#confirmReset').onclick=async e=>{e.target.disabled=true;try{S=await api('reset-cards',{confirm:true,revisions});$('#modal').close();render();toast('Todas las tarjetas quedaron sin jugar');}catch(err){toast(err.message);e.target.disabled=false;}};}
let playersPage=1;
function matchingPlayers(){const query=normalizeSearch(playersQuery);return S.players.filter(p=>normalizeSearch([p.id,p.name,p.surname].join(' ')).includes(query));}
function playerPages(){return Math.max(1,Math.ceil(matchingPlayers().length/25));}
function filterPlayers(){const query=normalizeSearch(playersQuery);let visible=0;document.querySelectorAll('[data-player-search]').forEach(row=>{row.hidden=!row.dataset.playerSearch.includes(query);if(!row.hidden)visible++;});const empty=$('#players-empty');if(empty)empty.hidden=visible!==0;}
document.addEventListener('input',e=>{if(e.target.id==='players-search'){playersQuery=e.target.value;playersPage=1;refreshVisible();}});
async function deleteMaster(id,type=master){try{const check=await rawApi('master-delete-check?type='+encodeURIComponent(type)+'&id='+encodeURIComponent(id));if(!check.allowed){modal(`<h2>No se puede eliminar</h2><p>${esc(check.message)}</p><div class="form-actions">${button('Cerrar','data-action="close"')}</div>`);return;}modal(`<h2>Eliminar registro</h2>${type==='rosters'?'<p>Se eliminarán todos los vínculos Grupo–Jugador de este grupo, incluidos el capitán y el hoyo de salida. Los registros del grupo y de los jugadores se conservarán.</p>':''}${type==='members'?'<p>Se quitará al jugador de este grupo. El jugador y el grupo se conservarán.</p>':''}<p>¿Confirmas que deseas eliminar <strong>${esc(check.label)}</strong>?</p><div class="form-actions">${button('Cancelar','data-action="close"')}${button('Eliminar','id="confirm-master-delete"','danger')}</div>`);$('#confirm-master-delete').onclick=async e=>{e.target.disabled=true;try{S=await api('master-delete',{type,id,version:check.version,confirm:true});$('#modal').close();render();toast('Registro eliminado');}catch(err){toast(err.message);e.target.disabled=false;}};}catch(e){toast(e.message);}}
