 if(master==='members'){headers=['Grupo','Categoría','Jugador','Hoyo','Acciones'];rows=S.members.map(m=>[S.groups.find(g=>g.id===m.groupId)?.name||m.groupId,player(m.playerId)?.category||'—',name(m.playerId),m.start,button('Editar',`data-action="edit" data-id="${m.playerId}"`)+deleteIconButton(`data-action="delete-master" data-id="${m.playerId}"`)]);}
