function remoteActionConflict(before,after){if((before.tournamentGeneration||0)!==(after.tournamentGeneration||0))return 'Un administrador reinició el torneo. La acción anterior ya no es válida.';const active=document.activeElement,dialog=$('#modal'),formOpen=dialog?.open&&!!dialog.querySelector('form,canvas,#confirmReset,#confirmResetCard,#confirm-tournament-reset,#confirm-master-delete,#app-confirm,#confirm-save-hole'),editingHole=active?.matches('[data-hole]');const reset=Object.entries(before.cards).some(([id,c])=>!after.cards[id]||(c.generation||0)!==(after.cards[id].generation||0));if(reset&&(formOpen||editingHole))return 'Se reiniciaron, reabrieron o eliminaron tarjetas mientras trabajabas. Se cerró la acción anterior.';if((formOpen||editingHole)&&before.configVersion&&after.configVersion&&before.configVersion!==after.configVersion)return 'Otro dispositivo cambió permisos, integrantes, asignaciones o configuración. Se cerró la acción para evitar guardar datos anteriores.';if(dialog?.open&&dialog.querySelector('canvas')&&JSON.stringify(before.cards)!==JSON.stringify(after.cards))return 'Los resultados o el cierre de una tarjeta cambiaron mientras firmabas. Revisa la tarjeta y vuelve a firmar.';if(editingHole&&before.permissions[active.dataset.group]&&!after.permissions[active.dataset.group])return 'Esta tarjeta se cerró o ya no tienes permiso para editarla.';return ''; }
