function field(label,name,value='',type='text',attrs=''){const maximum=name==='password'?64:name==='id'?(master==='players'?15:20):name==='name'?(master==='players'?80:100):name==='surname'?80:null;if(maximum)attrs+=` maxlength="${maximum}"`;if(name==='id'&&master==='players')attrs+=' pattern="[0-9]{1,15}"';return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs} required></label>`;}
