function signatures(id){if(hasDraft(id)){toast('Revise y confirme los números pendientes antes de firmar');return;}if(!me().admin&&!S.rainFinalization&&stats(S.cards[id]).played!==18){toast('Complete los 18 hoyos antes de finalizar');return;}const captain=S.members.find(m=>m.groupId===id&&m.captain&&player(m.playerId)?.active),writer=S.assignments.find(a=>a.groupId===id);if(!captain||!writer){toast('Configure capitán y anotador antes de finalizar');return;}const revision=S.cards[id].revision,signedScores=JSON.stringify(S.cards[id].scores);
 modal(`<p class="eyebrow">CIERRE DE TARJETA</p><h2>Finalizar ${esc(S.groups.find(g=>g.id===id).name)}</h2><p>${stats(S.cards[id]).played<18?(me().admin?'Cierre administrativo con ':'Cierre por lluvia con ')+stats(S.cards[id]).played+'/18 hoyos. Los hoyos vacíos se conservarán sin jugar. ':''}Confirmen los golpes y firmen.</p>${[[writer.playerId,1],[captain.playerId,0]].map(([p,i])=>`<section class="signature-field"><label>${i?'Anotador':'Capitán '+esc(S.groups.find(g=>g.id===id).name)}: ${esc(name(p))}</label><canvas id="signature${i}" width="600" height="160" aria-label="Firma de ${esc(name(p))}"></canvas>${button('Limpiar',`data-clear="${i}"`)}</section>`).join('')}<div class="form-actions">${button('Finalizar tarjeta','id="confirmFinal"','primary')}</div>`);
 const ink=[false,false];for(let i=0;i<2;i++){const canvas=$('#signature'+i),ctx=canvas.getContext('2d');function clear(){ctx.fillStyle='white';ctx.fillRect(0,0,600,160);ctx.strokeStyle='#132d25';ctx.lineWidth=2.5;ctx.lineCap='round';ink[i]=false;}clear();let drawing=false;const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*600/r.width,(e.clientY-r.top)*160/r.height];};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));};canvas.onpointermove=e=>{if(drawing){ctx.lineTo(...point(e));ctx.stroke();ink[i]=true;}};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;$(`[data-clear="${i}"]`).onclick=clear;}
 $('#confirmFinal').onclick=async()=>{if(!ink.every(Boolean)){toast('Se requieren las dos firmas dibujadas');return;}try{if(JSON.stringify(S.cards[id].scores)!==signedScores)throw Error('Los golpes cambiaron mientras firmaban. Cierre y revise la tarjeta antes de firmar de nuevo.');S=await api('finalize',{groupId:id,revision,signatures:[0,1].map(i=>$('#signature'+i).toDataURL('image/jpeg',0.85))});$('#modal').close();render();toast(S.cards[id].finalized?.pending?'Esperando confirmación del cierre.':'Tarjeta finalizada.');}catch(e){toast(e.message);}};
}
async function download(id,format){if(!S.cards[id]?.finalized||S.cards[id].finalized.pending){toast('Finalice la tarjeta antes de descargarla');return;}if(hasDraft(id)){toast('Revise y confirme los números pendientes antes de descargar');return;}if(!engine.online||engine.record?.pending.some(o=>o.groupId===id)){toast('Sincronice la tarjeta antes de descargar la tarjeta confirmada en imagen o PDF. Puede guardar un respaldo local desde el aviso superior.');return;}if(!format){modal(`<h2>Descargar tarjeta</h2><p>Selecciona el formato de la tarjeta finalizada.</p><div class="form-actions">${button('Imagen (PNG)',`data-action="download-image" data-id="${id}" autofocus`,'primary')}${button('PDF',`data-action="download-pdf" data-id="${id}"`)}</div>`);return;}
if(format==='image'){try{const response=await fetch('/api/card-image?group='+encodeURIComponent(id));if(!response.ok){const body=await response.json();throw Error(body.error||'No se pudo descargar la tarjeta');}const scene=await response.json(),canvas=document.createElement('canvas');canvas.width=scene.width*3;canvas.height=scene.height*3;const ctx=canvas.getContext('2d');ctx.scale(3,3);ctx.fillStyle='#fff';ctx.fillRect(0,0,scene.width,scene.height);for(const item of scene.drawing){if(item.type==='rect'){ctx.fillStyle=item.color;ctx.fillRect(item.x,scene.height-item.y-item.h,item.w,item.h);}else if(item.type==='text'){ctx.fillStyle=item.color;ctx.font=(item.bold?'bold ':'')+item.size+'px Arial';ctx.fillText(item.value,item.x,scene.height-item.y);}else{const img=new Image();img.src=item.src;await img.decode();ctx.drawImage(img,item.x,scene.height-item.y-item.h,item.w,item.h);}}const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('No se pudo crear la imagen');const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Macarena-'+id+'.png';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$('#modal').close();}catch(e){toast(e.message);}return;}
$('#modal').close();const a=document.createElement('a');a.href='/api/card.pdf?group='+encodeURIComponent(id);a.download='Macarena-'+id+'.pdf';document.body.append(a);a.click();a.remove();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){if(b.dataset.tab==='cards'&&tab!=='cards')cardsQuery='';if(b.dataset.tab==='results'&&tab!=='results')resultsQuery='';tab=b.dataset.tab;render();return;}if(b.dataset.master){master=b.dataset.master;render();return;}const id=b.dataset.id;await scoreCommit;try{switch(b.dataset.action){case 'clear-cards-search':clearCardsSearch();break;case 'logout':await api('logout',{});S=null;render();break;case 'close':$('#modal').close();break;case 'open-card':openGroupCard(id);break;case 'members':modal(`<p class="eyebrow">INTEGRANTES</p><h2>${esc(S.groups.find(g=>g.id===id).name)}</h2><div class="member-list">${S.members.filter(m=>m.groupId===id).map(m=>`<div><strong>${esc(name(m.playerId))}</strong><span>${esc(player(m.playerId).category)}${m.captain?' · Capitán':''}</span></div>`).join('')||'<p>Sin integrantes</p>'}</div>`);break;case 'reset-tournament':await resetTournament();break;case 'reset-card':resetCard(id);break;case 'reset-cards':resetCards();break;case 'delete-master':await deleteMaster(id);break;case 'roster-delete':await deleteMaster(id,'rosters');break;case 'roster-edit':rosterEditor(id);break;case 'roster-toggle':await toggleRoster(id);break;case 'new':editor();break;case 'edit':editor(id);break;case 'finalize':signatures(id);break;case 'download':await download(id);break;case 'download-pdf':await download(id,'pdf');break;case 'download-image':await download(id,'image');break;case 'reopen':if(await appConfirm('Reabrir tarjeta','Deberá recoger las dos firmas nuevamente.','Reabrir')){S=await api('reopen',{groupId:id});render();}break;}}catch(e){toast(e.message);}});
let scoreCommit=Promise.resolve();
function celebrate(el){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=el.getBoundingClientRect(),burst=document.createElement('div');burst.className='ace-burst';burst.setAttribute('aria-hidden','true');burst.style.left=(r.left+r.width/2)+'px';burst.style.top=(r.top+r.height/2)+'px';for(let i=0;i<24;i++){const spark=document.createElement('i');spark.style.setProperty('--x',`${Math.cos(i*Math.PI/12)*(65+i%4*18)}px`);spark.style.setProperty('--y',`${Math.sin(i*Math.PI/12)*(65+i%4*18)}px`);spark.style.background=['#e4bd4d','#1b9577','#e76e73'][i%3];burst.append(spark);}document.body.append(burst);setTimeout(()=>burst.remove(),1300);}
async function commitScore(el){const id=el.dataset.group,hole=Number(el.dataset.hole),value=el.value;let score;try{score=MacarenaScoring.parse(value);}catch(e){el.setAttribute('aria-invalid','true');el.closest('.card').querySelector('.score-error').textContent=e.message+' · Hoyo '+(hole+1);return false;}if(hasPending(id)){updateSyncStatus();return false;}const original=readHoleBase(el);if(original&&(original.version!==(S.cards[id].holeVersions?.[hole]||0)||original.score!==S.cards[id].scores[hole]||original.generation!==(S.cards[id].generation||0))){restoreConfirmedHole(el,'El hoyo cambió en otro dispositivo mientras lo editabas. No se sobrescribió.');return false;}if(score===S.cards[id].scores[hole]&&!hasPending(id)){clearHoleBase(el);localStorage.removeItem(draftKey(id,hole));return true;}try{MacarenaScoring.validateSequence(S.cards[id].scores,start(id),hole,score);}catch(e){restoreConfirmedHole(el,e.message);return false;}busy=true;try{const previous=S.cards[id].scores[hole],base=readHoleBase(el);S=await api('score',{groupId:id,hole,score,...(base?{baseScore:base.score,baseVersion:base.version,baseGeneration:base.generation}:{})});clearHoleBase(el);clearHoleBase(el);localStorage.removeItem(draftKey(id,hole));el.value=String(S.cards[id].scores[hole]??'');acceptedHoleValues.set(el,el.value);el.removeAttribute('aria-invalid');const [color,label]=result(score,S.course.pars[hole]);el.closest('label').className='hole '+color+(hole===start(id)-1?' starting-hole':'');el.closest('label').title=label;const card=el.closest('.card');card.querySelector('.score-error').textContent='';card.querySelector('.card-score').innerHTML=cardSummary(S.cards[id]);card.querySelectorAll('.half-total').forEach(n=>n.innerHTML=halfSummary(S.cards[id],Number(n.dataset.offset)));card.querySelectorAll('[data-hole]').forEach(input=>input.disabled=!S.permissions[id]||!MacarenaScoring.canRecord(S.cards[id].scores,start(id),Number(input.dataset.hole)));card.querySelector('.sequence-note').textContent=sequenceNote(id);const close=card.querySelector('[data-action="finalize"]');if(close){close.disabled=!S.permissions[id]||!me().admin&&!S.rainFinalization&&stats(S.cards[id]).played!==18;close.textContent=me().admin&&stats(S.cards[id]).played!==18?'Finalizar como admin':'Finalizar y firmar';}if(score===1&&previous!==1)celebrate(el);return true;}catch(e){if(!hasPending(id))restoreConfirmedHole(el,e.message);else toast(e.message);return false;}finally{busy=false;updateSyncStatus();}}
function validateScoreInput(el){const message='Solo números enteros entre 1 y 19. No se permiten decimales. Este dato no se guardó.';try{MacarenaScoring.parse(el.value);el.setCustomValidity('');el.removeAttribute('aria-invalid');el.closest('.card').querySelector('.score-error').textContent=draftErrors(el.dataset.group);return true;}catch{const wasInvalid=el.getAttribute('aria-invalid')==='true';el.setCustomValidity(message);el.setAttribute('aria-invalid','true');el.closest('.card').querySelector('.score-error').textContent='Hoyo '+(Number(el.dataset.hole)+1)+': '+message;if(!wasInvalid)toast(message);return false;}}
const acceptedHoleValues=new WeakMap();
function validHoleText(value){return /^(?:[1-9]|1[0-9])?$/.test(value);}
function rejectedHoleInput(){toast('Solo se permiten golpes enteros entre 1 y 19.');}
document.addEventListener('beforeinput',e=>{const el=e.target;if(!el.matches('[data-hole]')||!e.inputType.startsWith('insert'))return;const text=e.data??e.dataTransfer?.getData('text/plain');if(text==null)return;const value=el.value.slice(0,el.selectionStart)+text+el.value.slice(el.selectionEnd);if(!validHoleText(value)){e.preventDefault();rejectedHoleInput();}});
document.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-hole]'))return;if(!validHoleText(el.value)){el.value=acceptedHoleValues.get(el)??String(S.cards[el.dataset.group].scores[Number(el.dataset.hole)]??'');rejectedHoleInput();validateScoreInput(el);return;}acceptedHoleValues.set(el,el.value);rememberHoleBase(el);try{localStorage.setItem(draftKey(el.dataset.group,el.dataset.hole),el.value);}catch{toast('No se pudo conservar este número en el dispositivo');}validateScoreInput(el);updateCardFeedback(el.closest('.card'));});
document.addEventListener('focusin',e=>{const el=e.target;if(!el.matches('[data-hole]'))return;acceptedHoleValues.set(el,el.value);validateScoreInput(el);captureHoleBase(el);el.select();el.addEventListener('pointerup',()=>{if(document.activeElement===el)el.select();},{once:true});});
document.addEventListener('change',e=>{if(e.target.matches('[data-hole]')&&!holePopupActive)showHolePopup(e.target);});
document.addEventListener('keydown',e=>{const el=e.target;if(!el.matches('[data-hole]')||e.key!=='Enter')return;e.preventDefault();if(el.value!==String(S.cards[el.dataset.group].scores[Number(el.dataset.hole)]??''))showHolePopup(el);else{const next=MacarenaScoring.nextHole(S.cards[el.dataset.group].scores,start(el.dataset.group));el.closest('.card').querySelector(`[data-hole="${next}"]`)?.focus();}});
document.addEventListener('focusout',e=>{if(e.target.matches('[data-hole]'))setTimeout(async()=>{await scoreCommit;if(!document.activeElement?.matches('[data-hole]')&&!busy&&!$('#modal').open)render();},150);});

const offlineStore=new MacarenaOffline.Store();
let syncRequested=false;let shellReady=false,storageReady=true,events=null,setupDone=false,forceLogin=false,networkTask=null;
const engine=new MacarenaOffline.Engine({store:offlineStore,transport:rawApi,waitForConfirmation:true,onChange:(snapshot)=>{if(setupDone&&engine.auth){forceLogin=true;S=null;$('#modal')?.close();events?.close();events=null;render();return;}const conflict=snapshot&&S&&!localActionCount?remoteActionConflict(S,snapshot):'';if(conflict){$('#modal')?.close();document.activeElement?.blur?.();}const roleChanged=!!snapshot&&!!S&&!!snapshot.players.find(p=>p.id===snapshot.me)?.admin!==!!me().admin;if(roleChanged&&!snapshot.players.find(p=>p.id===snapshot.me)?.admin)tab='cards';const tournamentChanged=!!snapshot&&!!S&&(snapshot.tournamentGeneration||0)!==(S.tournamentGeneration||0);if(tournamentChanged){$('#modal')?.close();resultsQuery='';playersQuery='',cardsQuery='',rosterQuery='';}if(snapshot&&!forceLogin){for(const [id,c] of Object.entries(snapshot.cards)){const key='macarena-reset:'+snapshot.me+':'+id;if(c.resetGeneration>Number(localStorage.getItem(key)||0)){for(let h=0;h<18;h++)localStorage.removeItem(`macarena-input:${snapshot.me}:${id}:${h}`);localStorage.setItem(key,String(c.resetGeneration));}}S=snapshot;}if(setupDone){if(conflict||tournamentChanged||roleChanged)render();else if(!busy&&!$('#modal').open)render(true);else updateSyncStatus();if(conflict){modal(`<h2>Acción interrumpida</h2><p>${esc(conflict)}</p><p>La vista está actualizada. Revisa los datos antes de continuar.</p><div class="form-actions">${button('Entendido','data-action="close"','primary')}</div>`);}}}});
const offlineBoot=(async()=>{try{await offlineStore.ready;const id=localStorage.getItem('macarena-active-user');if(id)await engine.restore(id);}catch{storageReady=false;}if('serviceWorker' in navigator&&window.isSecureContext){navigator.serviceWorker.register('/sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{shellReady=true;updateSyncStatus();}).catch(()=>{shellReady=false;});}})();
let wireParts={},wireManifest={};
async function rawApi(path,data){if(path==='login'||path==='logout'){wireParts={};wireManifest={};}const r=await fetch('/api/'+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:path==='state'?{'X-Macarena-State':JSON.stringify(wireManifest)}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(10000)});const j=await r.json();if(!r.ok){const e=Error(j.error||'No se pudo conectar');e.status=r.status;e.tournamentGeneration=j.tournamentGeneration;throw e;}if(path==='state'&&j.stateDelta){for(const key of j.removed)delete wireParts[key];Object.assign(wireParts,j.patch);wireManifest=j.manifest;const full={cards:{}};for(const [key,value] of Object.entries(wireParts)){if(key.startsWith('card:'))full.cards[key.slice(5)]=value;else full[key]=value;}return structuredClone(full);}return j;}
async function syncNow(){syncRequested=true;if(networkTask)return networkTask;networkTask=(async()=>{do{syncRequested=false;if(navigator.locks)await navigator.locks.request('macarena-sync',()=>engine.sync());else await engine.sync();}while(syncRequested);})().finally(()=>networkTask=null);return networkTask;}
function connectLive(){if(events||!engine.user)return;events=new EventSource('/api/events');events.addEventListener('changed',()=>syncNow());events.onerror=()=>{engine.online=false;updateSyncStatus();};}
async function api(path,data){if(data&&S?.configVersion)data={...data,baseConfigVersion:$('#modal')?.open?(modalConfigVersion||S.configVersion):S.configVersion};if(data)localActionCount++;try{return await performApi(path,data);}finally{if(data)localActionCount--;}}
async function performApi(path,data){await offlineBoot;
 if(path==='login'){if(engine.record?.pending.length&&data.id!==engine.user)throw Error('Hay golpes pendientes. Ingrese con la misma cédula para sincronizarlos.');await rawApi(path,data);const next=await rawApi('state');forceLogin=false;engine.user=next.me;await engine.accept(next);localStorage.setItem('macarena-active-user',next.me);navigator.storage?.persist?.().catch(()=>{});connectLive();syncNow();return {ok:true};}
 if(path==='state'){if(engine.user){await syncNow();if(engine.record?.snapshot)return MacarenaOffline.view(engine.record);}const next=await rawApi('state');engine.user=next.me;await engine.accept(next);localStorage.setItem('macarena-active-user',next.me);connectLive();return MacarenaOffline.view(engine.record);}
 if(path==='score'){if(!storageReady)throw Error('El navegador no permite guardar en este dispositivo');await engine.queue('score',data);localStorage.removeItem(draftKey(data.groupId,data.hole));updateSyncStatus();await syncNow();if(engine.record.pending.some(o=>o.groupId===data.groupId))throw Error('El golpe está protegido. Espere la confirmación para continuar.');return MacarenaOffline.view(engine.record);}
 if(path==='finalize'){const c=S.cards[data.groupId],captain=S.members.find(m=>m.groupId===data.groupId&&m.captain&&player(m.playerId)?.active),writer=S.assignments.find(a=>a.groupId===data.groupId);await engine.queue('finalize',{...data,captain:captain?.playerId,writer:writer?.playerId});updateSyncStatus();await syncNow();return MacarenaOffline.view(engine.record);}
 if(path==='logout'){if(engine.record?.pending.length)throw Error('Hay datos pendientes. Sincronícelos antes de cerrar sesión; puede cerrar la aplicación sin cerrar sesión.');await rawApi(path,data);localStorage.removeItem('macarena-active-user');await offlineStore.change(engine.user,()=>({snapshot:null,pending:[]}));engine.user=null;engine.record=null;events?.close();events=null;return {ok:true};}
 try{const result=await rawApi(path,data);engine.online=true;if(result.cards){await engine.accept(result);return MacarenaOffline.view(engine.record);}return result;}catch(e){if(!e.status){engine.online=false;updateSyncStatus();throw Error('Esta acción necesita conexión. Los golpes pendientes siguen guardados.');}throw e;}
}
function syncMarkup(){
 if(!engine.record)return '';
 const pending=engine.record.pending,blocked=pending.find(o=>o.problem);
 if(!storageReady)return '<div class="sync-notice attention" role="alert">No se puede guardar en este celular. No continúe registrando golpes.</div>';
 if(engine.auth)return `<div class="sync-notice attention" role="alert">Vuelva a ingresar para terminar de guardar. ${button('Ingresar','data-action="reauth"')}</div>`;
 if(!pending.length)return engine.online?'':'<div class="sync-notice" role="status">Sin conexión. El siguiente golpe deberá esperar a que vuelva la señal para confirmarse.</div>';
 if(blocked)return `<div class="sync-notice attention" role="alert"><div><strong>No se pudo confirmar el hoyo ${blocked.hole===undefined?'':blocked.hole+1}.</strong><span>${esc(blocked.problem||'No se pudo confirmar este golpe. Su registro sigue protegido.')}</span></div>${me()?.admin?button('Revisar golpe','data-action="review-sync"'):''}</div>`;
 return `<div class="sync-notice" role="status"><span class="save-spinner" aria-hidden="true"></span><div><strong>${engine.online?'Guardando…':'Esperando conexión…'}</strong><span>Espere para continuar. Su golpe está protegido y se enviará automáticamente.</span></div></div>`;
}
function updateSyncStatus(){const node=$('#sync-status');if(node)node.innerHTML=syncMarkup();if(!S)return;document.querySelectorAll('[data-card]').forEach(card=>{const id=card.dataset.card,c=S.cards[id];if(!c){card.remove();return;}card.setAttribute('aria-busy',String(hasPending(id)));card.querySelectorAll('[data-hole]').forEach(el=>el.disabled=hasPending(id)||!S.permissions[id]||!MacarenaScoring.canRecord(c.scores,start(id),Number(el.dataset.hole)));const close=card.querySelector('[data-action="finalize"]');if(close)close.disabled=hasPending(id)||!S.permissions[id]||stats(c).played!==18&&!me().admin&&!S.rainFinalization;const note=card.querySelector('.sequence-note');if(note)note.textContent=c.finalized?'':sequenceNote(id);updateCardFeedback(card);});}

function render(partial=false){if(partial&&S&&$('#content')){refreshVisible();return;}const historyOpen=$('#settings-history')?.open;baseRender();if(historyOpen&&$('#settings-history'))$('#settings-history').open=true;if(S){const content=$('#content');const banner=document.createElement('div');banner.id='sync-status';content.before(banner);updateSyncStatus();if(tab==='results')filterResults();if(tab==='masters'&&master==='players')filterPlayers();if(tab==='settings')filterHistory();filterLists();}}
function backupLocal(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(engine.record,null,2)],{type:'application/json'}));a.href=url;a.download='Macarena-respaldo-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reviewSync(){if(!me()?.admin){toast('Pida al administrador que revise la tarjeta');return;}const groups=[...new Set(engine.record.pending.map(o=>o.groupId))];modal(`<h2>Datos pendientes</h2><p>Los cambios siguen guardados en este celular. Si cambió el permiso, el administrador debe habilitarlo antes de reintentar.</p>${groups.map(id=>`<section class="sync-review"><h3>${esc(S.groups.find(g=>g.id===id)?.name||id)}</h3>${engine.record.pending.filter(o=>o.groupId===id).map(o=>`<p>${o.type==='score'?`Hoyo ${o.hole+1}: <b>${o.score??'Sin jugar'}</b> en este celular · Servidor: ${engine.record.snapshot.cards[id]?.scores[o.hole]??'Sin jugar'}`:'Dos firmas y finalización pendientes'}${o.problem?`<br><strong>${o.status===403?'Revise la autorización del anotador.':o.status===409?'El resultado cambió en otro dispositivo.':'No se confirmó el guardado. Reintente.'}</strong>`:''}</p>`).join('')}${button('Conservar datos del servidor',`data-discard-group="${id}"`)}</section>`).join('')}<div class="form-actions">${button('Guardar respaldo','data-action="backup-local"')}${button('Reintentar envío','data-action="retry-sync"','primary')}</div>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.discardGroup&&me()?.admin){if(await appConfirm('Usar los datos del servidor','Se descartarán TODOS los golpes y firmas pendientes de este grupo en el celular. Guarde un respaldo si necesita conservarlos.','Usar datos del servidor','danger')){await engine.discardGroup(b.dataset.discardGroup);$('#modal').close();render();}}switch(b.dataset.action){case 'sync':await syncNow();break;case 'retry-sync':await engine.retry();$('#modal').close();render();break;case 'review-sync':reviewSync();break;case 'backup-local':backupLocal();break;case 'reauth':forceLogin=true;S=null;render();break;}}catch(e){toast(e.message);}});
window.addEventListener('online',()=>{syncNow();connectLive();});window.addEventListener('offline',()=>{engine.online=false;updateSyncStatus();});document.addEventListener('visibilitychange',()=>{if(!document.hidden){syncNow();connectLive();}});window.addEventListener('focus',()=>syncNow());
async function refresh(){await syncNow();connectLive();}

(async()=>{await offlineBoot;setupDone=true;if(engine.record?.snapshot){S=MacarenaOffline.view(engine.record);render();connectLive();syncNow();}else{try{S=await api('state');}catch{}render();}})();setInterval(()=>{if(engine.user)refresh();},15000);
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const tools=[{name:'macarena_read_results',description:'Consultar los resultados actuales de los grupos de Macarena con la sesión iniciada.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},async execute(){S=await api('state');render();return S.groups.filter(g=>g.active).map(g=>({group:g.id,name:g.name,...stats(S.cards[g.id])}));}},{name:'macarena_record_score',description:'Guardar los golpes de un hoyo de una tarjeta. Requiere permiso de anotador o administrador y tarjeta abierta.',inputSchema:{type:'object',properties:{groupId:{type:'string'},hole:{type:'integer',minimum:1,maximum:18},score:{type:'integer',minimum:1,maximum:19}},required:['groupId','hole','score'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!Number.isInteger(input.hole)||input.hole<1||input.hole>18||!Number.isInteger(input.score)||input.score<1||input.score>19)throw Error('Hoyo o score inválido');S=await api('state');if(!S.cards[input.groupId])throw Error('Grupo no encontrado');S=await api('score',{groupId:input.groupId,hole:input.hole-1,score:input.score,revision:S.cards[input.groupId].revision});render();return {group:input.groupId,...stats(S.cards[input.groupId])};}}];
 for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
}




function rosterControls(){return `<p class="muted">Selecciona grupo, hoyo e integrantes. Guarda y cierra el grupo cuando termines. Para agregar más, usa Abrir grupo.</p><div class="board-search"><input id="roster-search" type="search" value="${esc(rosterQuery)}" placeholder="Buscar grupo" aria-label="Buscar grupo"></div><p id="roster-empty" class="muted" hidden>No hay grupos que coincidan.</p><div class="roster-controls">${S.groups.map(g=>`<div data-roster-search="${esc(normalizeSearch(g.name))}"><span>${esc(g.name)} · ${g.rosterClosed?'Cerrado':'Abierto'}</span><div>${!g.rosterClosed?button('Integrantes',`data-action="roster-edit" data-id="${g.id}"`):button(eye,`data-action="members" data-id="${g.id}" aria-label="Ver integrantes de ${esc(g.name)}" title="Ver integrantes"`,'eye')}${button(g.rosterClosed?'Abrir grupo':'Cerrar grupo',`data-action="roster-toggle" data-id="${g.id}"`)}${button(trashIcon+' Eliminar',`data-action="roster-delete" data-id="${esc(g.id)}" aria-label="Eliminar todos los integrantes de ${esc(g.name)}" ${S.members.some(m=>m.groupId===g.id)?'':'disabled'}`,'danger')}</div></div>`).join('')}</div>`;}
async function toggleRoster(id){const g=S.groups.find(g=>g.id===id);if(!g)return;if(!await appConfirm(g.rosterClosed?'Abrir grupo':'Cerrar grupo',`${g.rosterClosed?'Abrir':'Cerrar'} la conformación de ${g.name}?`,g.rosterClosed?'Abrir grupo':'Cerrar grupo'))return;try{S=await api('roster',{groupId:id,action:g.rosterClosed?'open':'close',baseMembers:S.members.filter(m=>m.groupId===id),baseClosed:!!g.rosterClosed});render();}catch(e){toast(e.message);}}
function rosterEditor(id){const groups=S.groups.filter(g=>g.active&&!g.rosterClosed);if(id&&!groups.some(g=>g.id===id)){toast('El grupo está cerrado. Usa Abrir grupo para editar sus integrantes.');return;}if(!groups.length){toast('No hay grupos abiertos. Usa Abrir grupo en Grupo–Jugador.');return;}
modal(`<p class="eyebrow">GRUPO–JUGADOR</p><h2>Seleccionar integrantes</h2><form id="editor"><div class="form-grid">${select('Grupo','groupId',groups.map(g=>[g.id,g.name]),id)}${select('Hoyo','start',Array.from({length:18},(_,i)=>[i+1,'Hoyo '+(i+1)]),'')}<fieldset class="roster-members"><legend>Integrantes (uno o varios)</legend><input id="roster-member-search" type="search" placeholder="Buscar por cédula o nombre" aria-label="Buscar integrantes"><p id="roster-selected" class="muted" role="status"></p><div id="roster-options"></div></fieldset>${select('Capitán del grupo','captainId',[],'')}</div><p class="muted">Los integrantes seleccionados aparecen primero. Los asignados a otros grupos no están disponibles. Cierra el grupo cuando termines; podrás abrirlo desde el maestro.</p><p class="form-error" role="alert"></p><div class="form-actions"><button type="submit" class="primary">Guardar</button><button type="submit" name="closeGroup" value="yes">Guardar y cerrar grupo</button></div></form>`);
const form=$('#editor'),groupSelect=form.elements.groupId,hole=form.elements.start;let baseMembers=[],baseClosed=false;
const refreshCaptain=()=>{const control=form.elements.captainId,current=control.value,selected=[...form.querySelectorAll('[name=playerIds]:checked')].map(n=>n.value);control.innerHTML='<option value="">Seleccionar</option>'+S.players.filter(p=>p.active&&selected.includes(p.id)).map(p=>`<option value="${esc(p.id)}">${esc(name(p.id))}</option>`).join('');control.value=current;const count=selected.length;$('#roster-selected').textContent=count+' integrante'+(count===1?'':'s')+' seleccionado'+(count===1?'':'s');};form.elements.captainId.required=false;
const update=()=>{const gid=groupSelect.value;$('#roster-member-search').value='';baseMembers=structuredClone(S.members.filter(m=>m.groupId===gid));baseClosed=!!S.groups.find(g=>g.id===gid)?.rosterClosed;hole.value=baseMembers[0]?.start||'';const selected=new Set(baseMembers.map(m=>m.playerId));const available=gid?S.players.filter(p=>selected.has(p.id)||(p.active&&!S.members.some(m=>m.playerId===p.id))):[];available.sort((a,b)=>Number(selected.has(b.id))-Number(selected.has(a.id))||name(a.id).localeCompare(name(b.id),'es'));$('#roster-options').innerHTML=available.map(p=>`<label data-member-search="${esc(normalizeSearch(p.id+' '+name(p.id)))}"><input type="checkbox" name="playerIds" value="${esc(p.id)}" ${selected.has(p.id)?'checked':''}><span>${esc(name(p.id))} <small>${esc(p.category)}</small></span></label>`).join('')||'<p class="muted">Selecciona un grupo para ver los integrantes disponibles.</p>';refreshCaptain();form.elements.captainId.value=baseMembers.find(m=>m.captain)?.playerId||'';};groupSelect.onchange=update;$('#roster-options').addEventListener('change',refreshCaptain);$('#roster-member-search').oninput=e=>filterSearch('[data-member-search]','memberSearch',e.target.value);update();
form.onsubmit=async e=>{e.preventDefault();const close=e.submitter?.name==='closeGroup',buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{S=await api('roster',{action:'save',groupId:groupSelect.value,start:Number(hole.value),playerIds:new FormData(form).getAll('playerIds'),captainId:form.elements.captainId.value,baseMembers,baseClosed,close});$('#modal').close();render();toast(close?'Integrantes guardados y grupo cerrado':'Integrantes guardados');}catch(err){form.querySelector('.form-error').textContent=err.message;buttons.forEach(b=>b.disabled=false);}};
}
async function resetTournament(){try{const check=await rawApi('reset-tournament-check');modal(`<h2>Reiniciar Torneo</h2><p>Esta acción borra todas las tarjetas y resultados, asignaciones de tarjetas, grupo–jugador, grupos, jugadores no administradores e historial anterior.</p><p>Restablece Torneo y Cancha a sus valores iniciales y apaga edición y lluvia. Conserva los jugadores administradores, sus claves y el último logo cargado. No se puede deshacer desde la aplicación.</p><label>Escribe REINICIAR TORNEO<input id="reset-tournament-phrase" autocomplete="off"></label><div class="form-actions">${button('Cancelar','data-action="close"')}${button('Reiniciar Torneo','id="confirm-tournament-reset" disabled','danger')}</div>`);const input=$('#reset-tournament-phrase'),buttonEl=$('#confirm-tournament-reset');input.oninput=()=>{buttonEl.disabled=input.value!=='REINICIAR TORNEO';};buttonEl.onclick=async()=>{buttonEl.disabled=true;try{S=await api('reset-tournament',{version:check.version,confirm:true,phrase:input.value});$('#modal').close();render();toast('Torneo reiniciado. Puedes configurarlo desde cero.');}catch(e){toast(e.message);buttonEl.disabled=input.value!=='REINICIAR TORNEO';}};}catch(e){toast(e.message);}}

// Validate generated fields before any native form submission, including whitespace-only text.
document.addEventListener('input',e=>{const el=e.target;if(!el.matches('#editor input'))return;if(['name','surname','title','subtitle'].includes(el.name)){el.setCustomValidity(el.value.trim()&&!el.value.includes('\0')?'':'Este campo requiere texto válido.');}});
document.addEventListener('submit',e=>{if(e.target.id!=='editor')return;for(const el of e.target.querySelectorAll('input'))if(['name','surname','title','subtitle'].includes(el.name))el.setCustomValidity(el.value.trim()&&!el.value.includes('\0')?'':'Este campo requiere texto válido.');if(!e.target.reportValidity()){e.preventDefault();e.stopImmediatePropagation();}},true);

async function loadHistory(){const request=++historyRequest,owner=S?.me,generation=S?.tournamentGeneration||0;const target=$('#history-content');if(!target||!me()?.admin)return;target.innerHTML='<p class="muted">Consultando historial…</p>';try{const query=new URLSearchParams({page:historyPage,from:historyFrom,to:historyTo,functionality:historyFilter});const result=await rawApi('history?'+query);if(request!==historyRequest||S?.me!==owner||(S.tournamentGeneration||0)!==generation)return;historyRows=result.generation===generation?result.audit:[];historyOwner=owner;historyGeneration=generation;historyPage=result.page;historyPages=result.pages;historyTotal=result.total;historyConsulted=new Date().toLocaleString('es-CO');const current=$('#history-content');if(current){current.innerHTML=historyTable();filterHistory();}}catch(e){const current=$('#history-content');if(current&&request===historyRequest){historyRows=[];historyTotal=0;historyPages=1;historyPage=1;historyConsulted='';current.innerHTML=historyTable()+'<p class="form-error" role="alert">'+esc(e.message)+'</p>'+button('Reintentar','data-history-query');filterHistory();}}}
document.addEventListener('click',e=>{const summary=e.target.closest('#settings-history > summary');if(summary&&!summary.parentElement.open){historyPage=1;loadHistory();}});


function filterSearch(selector,key,query,empty){let visible=0;document.querySelectorAll(selector).forEach(el=>{el.hidden=!el.dataset[key].includes(normalizeSearch(query));if(!el.hidden)visible++;});if(empty&&$(empty))$(empty).hidden=visible>0;}
function clearCardsSearch(){cardsQuery='';const input=$('#cards-search');if(input)input.value='';filterLists();input?.focus();}
function filterCards(){filterSearch('[data-card-search]','cardSearch',cardsQuery,'#cards-empty');const status=$('#cards-filter-status'),count=$('#cards-filter-count');if(status)status.hidden=!normalizeSearch(cardsQuery).trim();if(count){const cards=[...document.querySelectorAll('[data-card-search]')];count.textContent=`Mostrando ${cards.filter(card=>!card.hidden).length} de ${cards.length} tarjetas`;}}
function filterLists(){filterCards();filterSearch('[data-roster-search]','rosterSearch',rosterQuery,'#roster-empty');}
document.addEventListener('input',e=>{if(e.target.id==='cards-search'){cardsQuery=e.target.value;filterLists();}if(e.target.id==='roster-search'){rosterQuery=e.target.value;filterLists();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-history-page],[data-history-query]');if(!b||!me()?.admin)return;if(b.hasAttribute('data-history-page'))historyPage=Number(b.dataset.historyPage);else{historyPage=1;historyFrom=$('#history-from')?.value??historyFrom;historyTo=$('#history-to')?.value??historyTo;}loadHistory();});

// Reconcile live data without replacing the page, forms or unchanged controls.
function nodeKey(n){return n.nodeType===1?(n.id||n.dataset.card||n.dataset.resultGroup||''):'';}
function reconcile(old,next){
 if(old.nodeType!==next.nodeType||old.nodeName!==next.nodeName){const replacement=next.cloneNode(true);old.replaceWith(replacement);return replacement;}
 if(old.nodeType===3){if(old.data!==next.data)old.data=next.data;return old;}
 if(old.nodeType!==1||old.id==='history-content')return old;
 const active=old===document.activeElement;
 for(const a of [...old.attributes])if(!next.hasAttribute(a.name)&&a.name!=='open'&&a.name!=='hidden')old.removeAttribute(a.name);
 for(const a of next.attributes)if(old.getAttribute(a.name)!==a.value&&!(active&&a.name==='value'))old.setAttribute(a.name,a.value);
 if(old instanceof HTMLInputElement){if(!active&&old.value!==next.value)old.value=next.value;old.checked=next.checked;return old;}
 const keyed=new Map([...old.childNodes].map(n=>[nodeKey(n),n]).filter(([k])=>k));
 let cursor=old.firstChild;
 for(const wanted of [...next.childNodes]){const key=nodeKey(wanted);let current=key?keyed.get(key):cursor;if(current&&nodeKey(current)&&!key)current=null;if(!current){current=wanted.cloneNode(true);old.insertBefore(current,cursor);}else{if(current!==cursor)old.insertBefore(current,cursor);current=reconcile(current,wanted);}cursor=current.nextSibling;}
 while(cursor){const after=cursor.nextSibling;cursor.remove();cursor=after;}
 return old;
}
function refreshVisible(){const template=document.createElement('template');template.innerHTML=tab==='cards'?cards():tab==='results'?leaderboard():tab==='settings'?settings():masters();const next=document.createElement('section');next.id='content';next.append(template.content);reconcile($('#content'),next);const active=S.groups.filter(g=>g.active),values=[active.filter(g=>stats(S.cards[g.id]).played&&(!S.cards[g.id].finalized||S.cards[g.id].finalized.pending)).length,active.filter(g=>S.cards[g.id].finalized&&!S.cards[g.id].finalized.pending).length];document.querySelectorAll('.counters strong').forEach((el,i)=>{if(el.textContent!==String(values[i]))el.textContent=values[i];});const logo=$('header .brand img'),logoSrc='/tournament-logo.jpg?v='+(S.tournament?.logoVersion||'default');if(logo&&logo.getAttribute('src')!==logoSrc)logo.src=logoSrc;const who=$('.account-name');if(who)who.textContent=name(S.me);updateSyncStatus();if(tab==='results')filterResults();if(tab==='masters'&&master==='players')filterPlayers();filterLists();}


function appConfirm(title,message,label='Confirmar',style='primary'){
 return new Promise(resolve=>{
  modal(`<h2>${esc(title)}</h2><p>${esc(message)}</p><div class="form-actions">${button('Cancelar','data-action="close"')}${button(esc(label),'id="app-confirm"',style)}</div>`);
  const dialog=$('#modal');let accepted=false;
  dialog.addEventListener('close',()=>resolve(accepted),{once:true});
  $('#app-confirm').onclick=()=>{accepted=true;dialog.close();};
 });
}

function restoreConfirmedHole(el,message){
 const id=el.dataset.group,hole=Number(el.dataset.hole),card=el.closest('.card');
 clearHoleBase(el);localStorage.removeItem(draftKey(id,hole));el.value=String(S.cards[id].scores[hole]??'');acceptedHoleValues.set(el,el.value);el.setCustomValidity('');el.removeAttribute('aria-invalid');
 if(card){card.querySelector('.card-score').innerHTML=cardSummary(S.cards[id]);card.querySelectorAll('.half-total').forEach(n=>n.innerHTML=halfSummary(S.cards[id],Number(n.dataset.offset)));card.querySelector('.score-error').textContent=message+' Se restauró el valor confirmado del hoyo '+(hole+1)+'.';}
 modal(`<h2>El cambio no se guardó</h2><p>${esc(message)}</p><p>Hoyo ${hole+1}: se restauró el valor confirmado <strong>${esc(el.value||'Sin jugar')}</strong>. La suma corresponde a los golpes guardados.</p><div class="form-actions">${button('Aceptar','id="accept-score-warning" autofocus','primary')}</div>`);
 const dialog=$('#modal');dialog.querySelector('.close')?.remove();
 const preventCancel=e=>e.preventDefault();dialog.addEventListener('cancel',preventCancel);
 dialog.addEventListener('close',()=>dialog.removeEventListener('cancel',preventCancel),{once:true});
 $('#accept-score-warning').onclick=()=>dialog.close();
}



let holePopupActive=false;
function showHolePopup(el){
 const id=el.dataset.group,hole=Number(el.dataset.hole);
 if(!el.isConnected||busy||$('#modal').open||hasPending(id)||!S.permissions[id]||!validHoleText(el.value)||el.value===String(S.cards[id].scores[hole]??''))return;
 holePopupActive=true;
 const captain=groupCaptain(id);
 modal(`<h2>Hoyo ${hole+1} · ${el.value?'Golpes '+esc(el.value):'Borrar golpes'}</h2><p>${captain?'(Le anotas a &quot;'+esc(name(captain.id))+'&quot;)':'(Equipo sin capitán asignado)'}</p><div class="form-actions">${button('Guardar','id="confirm-save-hole" autofocus','primary')}</div>`);
 const dialog=$('#modal');let saving=false;dialog.addEventListener('close',()=>{holePopupActive=false;if(!saving&&el.isConnected){el.focus();updateCardFeedback(el.closest('.card'));}},{once:true});

 $('#confirm-save-hole').onclick=async()=>{saving=true;dialog.close();holePopupActive=false;scoreCommit=scoreCommit.then(()=>commitScore(el));if(await scoreCommit){const next=MacarenaScoring.nextHole(S.cards[id].scores,start(id));el.closest('.card')?.querySelector(`[data-hole="${next}"]`)?.focus();}};
}
document.addEventListener('pointerdown',e=>{
 const label=e.target.closest('.hole'),target=label?.querySelector('[data-hole]'),card=label?.closest('.card');
 if(!target||!card||!S||busy||$('#modal').open)return;
 const id=card.dataset.card,dirty=[...card.querySelectorAll('[data-hole]')].find(el=>el.value!==String(S.cards[id].scores[Number(el.dataset.hole)]??''));
 if(!dirty||target===dirty||!validHoleText(dirty.value))return;
 e.preventDefault();showHolePopup(dirty);
},true);

const holeEditBases=new WeakMap();
function baseKey(el){return draftKey(el.dataset.group,Number(el.dataset.hole))+':base';}
function captureHoleBase(el){const c=S.cards[el.dataset.group],h=Number(el.dataset.hole);holeEditBases.set(el,{score:c.scores[h],version:c.holeVersions?.[h]||0,generation:c.generation||0});}
function rememberHoleBase(el){if(localStorage.getItem(baseKey(el)))return;if(!holeEditBases.has(el))captureHoleBase(el);localStorage.setItem(baseKey(el),JSON.stringify(holeEditBases.get(el)));}
function readHoleBase(el){try{return JSON.parse(localStorage.getItem(baseKey(el)))||holeEditBases.get(el);}catch{return holeEditBases.get(el);}}
function clearHoleBase(el){localStorage.removeItem(baseKey(el));holeEditBases.delete(el);}
function confirmedCard(c){if(!S)return c;const id=Object.keys(S.cards).find(id=>S.cards[id]===c);return id&&hasPending(id)?engine.record?.snapshot?.cards[id]||c:c;}
function updateCardFeedback(card){if(!card)return;const id=card.dataset.card,node=card.querySelector('.card-save-state'),ops=engine.record?.pending.filter(o=>o.groupId===id)||[],dirty=[];card.querySelectorAll('[data-hole]').forEach(el=>{const pending=ops.some(o=>o.type==='score'&&o.hole===Number(el.dataset.hole)),changed=el.value!==String(S.cards[id].scores[Number(el.dataset.hole)]??'');el.closest('.hole').classList.toggle('hole-unsaved',changed&&!pending);el.closest('.hole').classList.toggle('hole-saving',pending);if(changed)dirty.push(Number(el.dataset.hole)+1);});if(!node)return;const problem=ops.find(o=>o.problem);node.classList.toggle('attention',!!problem||!!dirty.length);node.textContent=problem?'Hoyo '+(problem.hole+1)+': '+problem.problem:ops.length?(engine.online?'Guardando':'Esperando conexión')+' · Hoyo '+(ops[0].hole+1):dirty.length?'Sin guardar · Hoyo '+dirty.join(', ')+'. La suma corresponde a golpes confirmados.':'Guardado · '+stats(S.cards[id]).played+' hoyos confirmados';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-player-page]');if(!b)return;playersPage=Math.max(1,Math.min(playerPages(),Number(b.dataset.playerPage)));refreshVisible();});
